  (1, (timestamp '2026-10-26 08:00') at time zone 'Asia/Jerusalem', 'post', 'fixed', '{"app":"fanlife","hook":"On this day, 26 October — 5 clubs, one date.","body":"1988 · Celtic: Celtic 0-1 Bremen (European Cup) — 38 years ago\n1988 · Panathinaikos: CSKA Sofia 2-0 Panathinaikos (European Cup Winners'' Cup) — 38 years ago\n2000 · AEK Athens: AEK Athens 5-0 Herfølge — 26 years ago\n2011 · Hapoel Tel Aviv: Hapoel Ramat HaSharon 3-5 Hapoel Tel Aviv (Toto Cup) — 15 years ago\n2023 · Olympiacos: Olympiacos 2-1 West Ham (UEFA Europa League) — 3 years ago\n\nWhich one would you have been at? Every one of these clubs has its own archive in FAN LIFE.","visual":"T9-OTD On this day: 5 clubs as ticket stubs, crests from the shared library.","kit":{"t":"T9-OTD","data":{"date":"26 OCT","exact":true,"footerLabel":"FROM THE FAN LIFE ARCHIVE","rows":[{"year":1988,"club":"Celtic","crestName":"Celtic","line":"Celtic 0–1 Bremen","ago":"38 YEARS AGO · EUROPEAN CUP"},{"year":1988,"club":"Panathinaikos","crestName":"Panathinaikos","line":"CSKA Sofia 2–0 Panathinaikos","ago":"38 YEARS AGO · EUROPEAN CUP WINNERS'' CUP"},{"year":2000,"club":"AEK Athens","crestName":"AEK Athens","line":"AEK Athens 5–0 Herfølge","ago":"26 YEARS AGO"},{"year":2011,"club":"Hapoel Tel Aviv","crestName":"Hapoel Tel Aviv","line":"5–3 at Hapoel Ramat HaSharon","ago":"15 YEARS AGO · TOTO CUP"},{"year":2023,"club":"Olympiacos","crestName":"Olympiacos","line":"Olympiacos 2–1 West Ham","ago":"3 YEARS AGO · UEFA EUROPA LEAGUE"}]}}}'::jsonb),
