  (1, (timestamp '2026-10-26 16:00') at time zone 'Asia/Jerusalem', 'post', 'fixed', '{"app":"fanlife","url":"https://fanlife.dubelteam.com/clubs/celtic/trivia","hook":"Nerds only. Celtic — no Googling.","body":"Whose name went on the scoresheet for Celtic against Lazio in the UEFA Champions League on 4 Oct 2023?\n\nA) Ewan Henderson\nB) Kyogo Furuhashi\nC) Kobayashi Yuki\nD) Yamada Shin\n\nAnswer in the first comment (or the next story frame): Kyogo Furuhashi. Celtic 1-2 Lazio, UEFA Champions League, 4 Oct 2023. Kyogo Furuhashi scored for Celtic.\n\nThousands more like this — Expert level, Celtic trivia on FAN LIFE.","visual":"T10-NERDS Nerds only: the question and four answers, the club crest.","kit":{"t":"T10-NERDS","data":{"club":{"id":"celtic","name":"Celtic"},"crestName":"Celtic","question":"Whose name went on the scoresheet for Celtic against Lazio in the UEFA Champions League on 4 Oct 2023?","options":["Ewan Henderson","Kyogo Furuhashi","Kobayashi Yuki","Yamada Shin"],"level":"EXPERT"}}}'::jsonb),
