  (2, (timestamp '2026-10-27 19:00') at time zone 'Asia/Jerusalem', 'carousel', 'fixed', '{"app":"fanlife","url":"https://fanlife.dubelteam.com/clubs/celtic","hook":"Welcome to Paradise. A love letter to the Bhoys.","body":"In Parkhead, in Glasgow''s east end, with room for 60,411. Fans call it Paradise.\n\nFans call Celtic Park ''Paradise'' — the story goes it began as a joke about leaving the old ground behind.\n\nTag the Celtic fan who needs to see this. ❤️\nYour club has its own home on FAN LIFE — trivia, the archive, the shirts, a supporter''s life (link in bio).\n\n#Celtic #CelticFC #TheBhoys #COYBIG #FANLIFE #FootballForever","visual":"Carousel · love · Celtic: 4 slides in the club''s colours.","kit":{"t":"L-CAROUSEL","data":{"club":{"id":"celtic","name":"Celtic"}},"slides":[{"t":"L-SLIDE","data":{"club":{"id":"celtic","name":"Celtic"},"crestName":"Celtic","s":"cover","n":1,"of":4,"kicker":"GLASGOW · GREEN AND WHITE","title":"Welcome to Paradise."}},{"t":"L-SLIDE","data":{"club":{"id":"celtic","name":"Celtic"},"crestName":"Celtic","s":"love","n":2,"of":4,"big":"Celtic Park","line":"In Parkhead, in Glasgow''s east end, with room for 60,411. Fans call it Paradise.","shout":"HOME!","label":"CELTIC · FAN LIFE"}},{"t":"L-SLIDE","data":{"club":{"id":"celtic","name":"Celtic"},"crestName":"Celtic","s":"love","n":3,"of":4,"big":"The Bhoys","line":"Fans call Celtic Park ''Paradise'' — the story goes it began as a joke about leaving the old ground behind.","shout":"OURS!","label":"CELTIC · FAN LIFE"}},{"t":"L-SLIDE","data":{"club":{"id":"celtic","name":"Celtic"},"crestName":"Celtic","s":"cta","n":4,"of":4,"title":"Celtic has its own home on FAN LIFE. Come in."}}]}}'::jsonb),
